def compute(vars):
    repurchased = vars["v1"]
    authorized = vars["v2"]

    if authorized == 0:
        return None

    ratio = repurchased / authorized
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "repurchased_amount": repurchased,
            "authorized_amount": authorized,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
